def test_an_id_that_only_starts_like_a_real_one_fails():
    thesis, claims, values = case("AAPL swing")
    near = thesis.evidence[0][:11] + "00000000"
    assert near not in {claim.claim_id for claim in claims}
    got = p2(thesis.model_copy(update={"evidence": (*thesis.evidence, near)}), claims, values)
    assert got is False, (
        f"AAPL swing with {near} added to its evidence: it shares its first 11 characters with the real claim "
        f"{thesis.evidence[0]}, but no claim of the analysis has this id. An id names a claim only when every "
        f"character matches; p2_evidence_valid returned {got!r}"
    )

def test_inferences_are_still_evidence():
    for label in ("AAPL swing", "XOM swing"):
        thesis, claims, values = case(label)
        tags = {claim.claim_id: claim.tag for claim in claims}
        got = p2(thesis, claims, values)
        assert got is True, (
            f"{label} cites {', '.join(f'{cid} ({tags[cid]})' for cid in thesis.evidence)}; p2_evidence_valid "
            f"returned {got!r}. Rule 2 removes opinions only: an inference is evidence, its numbers were checked "
            f"against its parents at analyze time."
        )

def test_the_tolerance_is_relative_and_inclusive():
    for value, source, want in ((100.4, 100.0, True), (100.6, 100.0, False), (99.5, 100.0, True), (100.0, 99.5, True),
                                (-100.4, -100.0, True), (-100.6, -100.0, False)):
        got = hd_close(value, {"src_close_lab": source})
        assert got is want, (
            f"HD swing's close fact says {value}, its source holds {source}: the gap {abs(value - source):.2f} "
            f"against 0.5% of the larger magnitude, {0.005 * max(abs(value), abs(source)):.4f}, so it should "
            f"{'pass (at or inside the tolerance)' if want else 'fail'}; p2_evidence_valid returned {got!r}"
        )

def test_a_stop_on_the_level_fails():
    thesis, levels, atr, close = case("JPM swing")
    for stop, why in ((333.0, "exactly on pivot_low 333.0"), (333.5, "half a dollar above pivot_low 333.0")):
        got = p4(thesis.model_copy(update={"stop": stop}), levels, atr, close)
        assert got is False, (
            f"JPM swing (long, entry {thesis.entry.price}) with stop {stop}, {why}, the nearest level under the entry "
            f"(levels: {listed(levels)}). A stop on the level is taken by a retest of it; p4_levels_coherent "
            f"returned {got!r}"
        )

def test_the_allowance_boundary():
    for target, want, why in ((360.83, True, "on high_20"), (350.0, True, "before high_20"),
                              (364.85, True, "inside 360.83 + 4.0228"), (364.86, False, "a cent past 364.8528")):
        thesis, levels, atr, close = aapl(target)
        got = p4(thesis, levels, atr, close)
        assert got is want, (
            f"AAPL swing (long, entry {thesis.entry.price}, stop 338.69, ATR14 {atr:.4f}) with target {target}, "
            f"{why}, should {'pass' if want else 'fail'}; p4_levels_coherent returned {got!r}"
        )
